-- Create "offering_posts" table
CREATE TABLE "offering_posts" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "offering_id" integer NOT NULL, "author_id" integer NOT NULL, "title" text NOT NULL, "body" text NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"), CONSTRAINT "offering_posts_author_id_fkey" FOREIGN KEY ("author_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "offering_posts_offering_id_fkey" FOREIGN KEY ("offering_id") REFERENCES "offerings" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "idx_offering_posts_offering_id" to table: "offering_posts"
CREATE INDEX "idx_offering_posts_offering_id" ON "offering_posts" ("offering_id", "created_at" DESC);
-- Create "offering_post_comments" table
CREATE TABLE "offering_post_comments" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "post_id" integer NOT NULL, "parent_comment_id" integer NULL, "author_id" integer NOT NULL, "body" text NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"), CONSTRAINT "offering_post_comments_author_id_fkey" FOREIGN KEY ("author_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "offering_post_comments_parent_comment_id_fkey" FOREIGN KEY ("parent_comment_id") REFERENCES "offering_post_comments" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "offering_post_comments_post_id_fkey" FOREIGN KEY ("post_id") REFERENCES "offering_posts" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "idx_offering_post_comments_parent" to table: "offering_post_comments"
CREATE INDEX "idx_offering_post_comments_parent" ON "offering_post_comments" ("parent_comment_id");
-- Create index "idx_offering_post_comments_post_id" to table: "offering_post_comments"
CREATE INDEX "idx_offering_post_comments_post_id" ON "offering_post_comments" ("post_id", "created_at");

-- Row-level security at the service-role boundary: the judge role has no grant
-- on these tables, and the policy keeps it denied even if a future migration
-- grants too broadly. Added by hand because the Atlas community diff does not
-- model policies.
ALTER TABLE "offering_posts" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "runcodes_app_only" ON "offering_posts" TO PUBLIC
  USING (current_user = 'runcodes_app')
  WITH CHECK (current_user = 'runcodes_app');

ALTER TABLE "offering_post_comments" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "runcodes_app_only" ON "offering_post_comments" TO PUBLIC
  USING (current_user = 'runcodes_app')
  WITH CHECK (current_user = 'runcodes_app');
